"use client";

import { DashboardExpertService } from "@/data/api-client";
import { useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { SlotDialogState } from "@/types/expertDashboard/availability";
import { Button } from "@/components/ui";
import { Loader2, Plus, Trash2 } from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";
import { FieldError, FormErrorAlert } from "@/components/ui/form-message";
import { getApiErrorMessage } from "@/lib/api-errors";
import { scrollToFirstInvalidField } from "@/lib/form-utils";
import { API_ERROR_TOAST_ID } from "@/config/toast-config";

type SlotRow = {
    id?: number;
    from: string;
    to: string;
    originalFrom?: string;
    originalTo?: string;
    markedForDelete?: boolean;
};

export default function SlotDialog({
    state,
    expertId,
    onClose,
}: {
    state: SlotDialogState;
    expertId: number;
    onClose: () => void;
}) {
    const queryClient = useQueryClient();
    const { t } = useLanguage();

    const buildInitialRows = (): SlotRow[] => {
        if (state.slots && state.slots.length > 0) {
            return state.slots.map((s) => ({
                id: s.id ? Number(s.id) : undefined,
                from: s.from,
                to: s.to,
                originalFrom: s.from,  
                originalTo: s.to,     
            }));
        }
        return [{ from: "09:00", to: "17:00" }];
    };

    const [rows, setRows] = useState<SlotRow[]>(buildInitialRows);
    const [isPending, setIsPending] = useState(false);
    // Keyed by the row's index in `rows`.
    const [rowErrors, setRowErrors] = useState<Record<number, string>>({});
    const [generalError, setGeneralError] = useState<string | undefined>();

    const updateRow = (index: number, field: "from" | "to", value: string) => {
        setRows((prev) =>
            prev.map((row, i) => (i === index ? { ...row, [field]: value } : row))
        );
        if (rowErrors[index]) {
            setRowErrors((prev) => {
                const next = { ...prev };
                delete next[index];
                return next;
            });
        }
    };

    const addNewRow = () => {
        setRows((prev) => [...prev, { from: "09:00", to: "17:00" }]);
    };

    const removeRow = (index: number) => {
        const row = rows[index];
        setRowErrors({});
        if (row.id) {
            setRows((prev) =>
                prev.map((r, i) => (i === index ? { ...r, markedForDelete: true } : r))
            );
        } else {
            setRows((prev) => prev.filter((_, i) => i !== index));
        }
    };

    /** Per-row errors: both times required, start before end, and no overlap with another slot. */
    const validateRows = (): Record<number, string> => {
        const errors: Record<number, string> = {};
        const active = rows
            .map((row, index) => ({ row, index }))
            .filter(({ row }) => !row.markedForDelete);

        active.forEach(({ row, index }) => {
            if (!row.from || !row.to) errors[index] = t("experts.messages.fillAllTimeFields");
            else if (row.from.slice(0, 5) >= row.to.slice(0, 5)) errors[index] = t("experts.messages.startTimeBeforeEndTime");
        });

        const valid = active
            .filter(({ index }) => !errors[index])
            .sort((a, b) => a.row.from.localeCompare(b.row.from));
        for (let i = 1; i < valid.length; i++) {
            // Compare HH:mm only: the API may return "HH:mm:ss".
            if (valid[i].row.from.slice(0, 5) < valid[i - 1].row.to.slice(0, 5)) {
                errors[valid[i].index] = t("experts.settings.availability.slotsOverlap");
            }
        }
        return errors;
    };

    const handleSave = async () => {
        if (isPending) return;
        setGeneralError(undefined);

        const errors = validateRows();
        setRowErrors(errors);
        const firstError = Object.values(errors)[0];
        if (firstError) {
            toast.error(firstError);
            scrollToFirstInvalidField();
            return;
        }

        setIsPending(true);
        try {
            await Promise.all(
                rows.map((row) => {
                    if (row.markedForDelete && row.id) {
                        return DashboardExpertService.deleteAvailabilitySlot(expertId, row.id);
                    }

                    if (row.id) {
                        const isModified = row.from !== row.originalFrom || row.to !== row.originalTo;
                        if (!isModified) return Promise.resolve(); 
                        return DashboardExpertService.updateAvailabilitySlot(expertId, row.id, {
                            from: row.from,
                            to: row.to,
                        });
                    }

                    return DashboardExpertService.addAvailabilitySlot(expertId, {
                        day: state.day,
                        from: row.from,
                        to: row.to,
                    });
                })
            );

            queryClient.invalidateQueries({ queryKey: ["weekly-availability", expertId] });
            toast.success(t("experts.messages.availabilitySaveSuccess"));
            onClose();
        } catch (err: unknown) {
            // Some requests may have gone through; refresh the schedule behind the dialog.
            queryClient.invalidateQueries({ queryKey: ["weekly-availability", expertId] });
            const message = getApiErrorMessage(err, t, t("experts.messages.availabilitySaveFailed"));
            setGeneralError(message);
            toast.error(message, { id: API_ERROR_TOAST_ID });
        } finally {
            setIsPending(false);
        }
    };

    const visibleRows = rows.filter((r) => !r.markedForDelete);

    return (
        <Dialog open={state.open} onOpenChange={(open) => !open && !isPending && onClose()}>
            <DialogContent className="sm:max-w-[560px] p-0 gap-0 rounded-2xl overflow-hidden">

                <DialogHeader className="px-6 pt-6 pb-4 border-b border-[#F3F4F6]">
                    <DialogTitle className="capitalize text-[18px] font-[600] text-[#15042B]">
                        {state.mode === "edit" ? "Edit" : "Add"} {state.day} Availability
                    </DialogTitle>
                </DialogHeader>

                <div className="px-6 py-5 flex flex-col gap-3">
                    <FormErrorAlert message={generalError} />

                    {visibleRows.map((row, index) => {
                        const realIndex = rows.indexOf(row);
                        const rowError = rowErrors[realIndex];
                        const timeInputClass = `w-full border rounded-lg px-4 py-2.5 text-[14px] text-[#374151] bg-white focus:outline-none focus:ring-2 transition-colors ${rowError
                            ? "border-red-500 focus:ring-red-500/30 focus:border-red-500"
                            : "border-[#E5E7EB] focus:ring-[#0D9488]/30 focus:border-[#0D9488]"
                            }`;
                        return (
                        <div key={index} className="flex flex-col">
                        <div className="flex items-center gap-3">
                            <div className="flex-1">
                                <input
                                    type="time"
                                    dir="ltr"
                                    value={row.from}
                                    onChange={(e) => updateRow(realIndex, "from", e.target.value)}
                                    aria-invalid={!!rowError || undefined}
                                    className={timeInputClass}
                                />
                            </div>

                            <span className="text-[14px] text-[#6B7280] shrink-0">{t("experts.settings.timeOff.to")}</span>

                            <div className="flex-1">
                                <input
                                    type="time"
                                    dir="ltr"
                                    value={row.to}
                                    onChange={(e) => updateRow(realIndex, "to", e.target.value)}
                                    aria-invalid={!!rowError || undefined}
                                    className={timeInputClass}
                                />
                            </div>

                            {(visibleRows.length > 1 || row.id) && (
                                <button
                                    type="button"
                                    onClick={() => removeRow(realIndex)}
                                    disabled={isPending}
                                    className="p-1.5 rounded-md hover:bg-red-50 text-red-400 transition-colors shrink-0 disabled:opacity-50"
                                    title="Remove slot"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            )}
                        </div>
                        <FieldError message={rowError} />
                        </div>
                        );
                    })}

                    <button
                        type="button"
                        onClick={addNewRow}
                        disabled={isPending}
                        className="w-full mt-1 border border-dashed border-[#D1D5DB] rounded-lg py-2.5 text-[14px] text-[#6B7280] bg-[#F9FAFB] hover:bg-[#F3F4F6] transition-colors flex items-center justify-center gap-2"
                    >
                        <Plus className="w-4 h-4" />
                        Add Slot
                    </button>
                </div>

                <div className="h-px bg-[#F3F4F6]" />

                <DialogFooter className="px-6 py-4 flex flex-row justify-end gap-2">
                    <Button
                        variant="outline"
                        onClick={onClose}
                        disabled={isPending}
                        className="border-[#E5E7EB] text-[#4A5565] rounded-lg px-5"
                    >
                        Close
                    </Button>
                    <Button
                        onClick={handleSave}
                        disabled={isPending}
                        className="bg-[#0D9488] hover:bg-[#0B7C77] text-white rounded-lg px-6 font-[500]"
                    >
                        {isPending ? (
                            <>
                                <Loader2 className="w-4 h-4 me-2 animate-spin" />
                                {t("experts.common.saving")}
                            </>
                        ) : state.mode === "edit" ? "Save Changes" : "Add"}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}
